<template><main class="page-shell"><Sidebar/><section class="content"><RouterLink :to="`/groups/${route.params.id}`">← Назад кон настанот</RouterLink><section class="card reveal"><p class="eyebrow">🎁 МОЈ SECRET SANTA</p><template v-if="loading"><h2>Се вчитува...</h2></template><template v-else-if="assignment"><h1>Твојот подарок е за</h1><div class="person">{{assignment.receiverName}}</div><p>{{assignment.receiverEmail}}</p><h2>Wishlist</h2><div v-if="wishlist.length" class="wishes"><article v-for="item in wishlist" :key="item.id"><b>{{item.name}}</b><span>{{item.category}}<template v-if="item.price"> • {{item.price}} ден</template></span><a v-if="item.link" :href="item.link" target="_blank" rel="noopener">Линк ↗</a></article></div><p v-else>Овој корисник сè уште нема додадено желби.</p></template><template v-else><h1>Извлекувањето сè уште не е достапно.</h1></template></section></section></main></template>
<script setup>
import { onMounted,ref } from 'vue'; import { useRoute } from 'vue-router'; import Sidebar from '../components/Sidebar.vue'; import { useAuthStore } from '../stores/authStore'; import { getMyAssignment } from '../services/eventService'; import { getWishlist } from '../services/wishlistService';
const route=useRoute(),authStore=useAuthStore(),assignment=ref(null),wishlist=ref([]),loading=ref(true); onMounted(async()=>{try{assignment.value=await getMyAssignment(route.params.id,authStore.user.uid);if(assignment.value)wishlist.value=await getWishlist(assignment.value.receiverUid)}finally{loading.value=false}})
</script>
<style scoped>.reveal{max-width:760px;margin:30px auto;padding:44px;text-align:center}.eyebrow{color:var(--red);font-weight:900;letter-spacing:2px}.reveal h1{color:var(--dark-green)}.person{font-size:clamp(38px,7vw,70px);font-weight:900;color:var(--red);margin:24px 0 8px}.wishes{display:grid;gap:12px;text-align:left}.wishes article{background:white;border:1px solid var(--border);border-radius:14px;padding:16px;display:grid;gap:5px}.wishes span{color:var(--muted)}.wishes a{color:var(--green);font-weight:700}</style>
